export function getScheduleByDate(dateStr) {
  return MASTER_SCHEDULE.find(d => d.date === dateStr) || null;
}

export function getScheduleByDayNum(n) {
  return MASTER_SCHEDULE.find(d => d.dayNum === n) || null;
}